rewrite:
def render_html_toc(renderer: 'BaseRenderer', title: str, collapse: bool=
    False, **attrs: Any) ->str:
    toc = attrs.get('toc', [])
    html = render_toc_ul(toc)
    if collapse:
        html = '<details><summary>' + title + '</summary>\n' + html + '</details>\n'
    elif title:
        html = '<div class="toc">\n<span class="toc-title">' + title + '</span>\n' + html + '</div>\n'
    else:
        html = '<div class="toc">\n' + html + '</div>\n'
    return html


def _normalize_level(options: Dict[str, Any], name: str, default: Any) ->Any:
    if name not in options:
        return default
    value = options[name]
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        try:
            return int(value)
        except ValueError:
            return default
    return default
